CREATE TABLE "taxi_zone" (
  "locationid" smallint NOT NULL,
  "borough" character varying(30) NOT NULL,
  "zone" character varying(60),
  "service_zone" character varying(20),
  PRIMARY KEY ("locationid")
);

CREATE TABLE "green_trips" (
  "trip_id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "vendorid" smallint,
  "pickup_datetime" timestamp(6) without time zone NOT NULL,
  "dropoff_datetime" timestamp(6) without time zone NOT NULL,
  "store_and_fwd_flag" character(1),
  "ratecodeid" smallint,
  "pulocationid" smallint,
  "dolocationid" smallint,
  "passenger_count" smallint,
  "trip_distance" double precision,
  "fare_amount" numeric(10,2),
  "extra" numeric(10,2),
  "mta_tax" numeric(10,2),
  "tip_amount" numeric(10,2),
  "tolls_amount" numeric(10,2),
  "ehail_fee" numeric(10,2),
  "improvement_surcharge" numeric(10,2),
  "total_amount" numeric(10,2),
  "payment_type" smallint,
  "trip_type" smallint,
  "congestion_surcharge" numeric(10,2),
  "cbd_congestion_fee" numeric(10,2),
  PRIMARY KEY ("trip_id")
);

CREATE INDEX "taxi_zone_ix_taxi_zone_borough" ON "taxi_zone" ("borough");
CREATE INDEX "green_trips_ix_green_trips_do" ON "green_trips" ("dolocationid");
CREATE INDEX "green_trips_ix_green_trips_pickup" ON "green_trips" ("pickup_datetime");
CREATE INDEX "green_trips_ix_green_trips_pu" ON "green_trips" ("pulocationid");

ALTER TABLE "green_trips" ADD CONSTRAINT "fk_green_trips_do" FOREIGN KEY ("dolocationid") REFERENCES "taxi_zone" ("locationid") ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "green_trips" ADD CONSTRAINT "fk_green_trips_pu" FOREIGN KEY ("pulocationid") REFERENCES "taxi_zone" ("locationid") ON UPDATE NO ACTION ON DELETE NO ACTION;

CREATE VIEW "v_green_daily" ("trip_date", "trips", "revenue", "avg_distance") AS
SELECT CAST("green_trips"."pickup_datetime" AS DATE) AS "trip_date", COUNT(0) AS "trips", ROUND(SUM("green_trips"."total_amount"), 2) AS "revenue", ROUND(CAST(AVG("green_trips"."trip_distance") AS DECIMAL), 4) AS "avg_distance" FROM "green_trips" GROUP BY CAST("green_trips"."pickup_datetime" AS DATE);

CREATE VIEW "v_suspect_trips" ("trip_id", "vendorid", "pickup_datetime", "dropoff_datetime", "store_and_fwd_flag", "ratecodeid", "pulocationid", "dolocationid", "passenger_count", "trip_distance", "fare_amount", "extra", "mta_tax", "tip_amount", "tolls_amount", "ehail_fee", "improvement_surcharge", "total_amount", "payment_type", "trip_type", "congestion_surcharge", "cbd_congestion_fee") AS
SELECT "green_trips"."trip_id" AS "trip_id", "green_trips"."vendorid" AS "vendorid", "green_trips"."pickup_datetime" AS "pickup_datetime", "green_trips"."dropoff_datetime" AS "dropoff_datetime", "green_trips"."store_and_fwd_flag" AS "store_and_fwd_flag", "green_trips"."ratecodeid" AS "ratecodeid", "green_trips"."pulocationid" AS "pulocationid", "green_trips"."dolocationid" AS "dolocationid", "green_trips"."passenger_count" AS "passenger_count", "green_trips"."trip_distance" AS "trip_distance", "green_trips"."fare_amount" AS "fare_amount", "green_trips"."extra" AS "extra", "green_trips"."mta_tax" AS "mta_tax", "green_trips"."tip_amount" AS "tip_amount", "green_trips"."tolls_amount" AS "tolls_amount", "green_trips"."ehail_fee" AS "ehail_fee", "green_trips"."improvement_surcharge" AS "improvement_surcharge", "green_trips"."total_amount" AS "total_amount", "green_trips"."payment_type" AS "payment_type", "green_trips"."trip_type" AS "trip_type", "green_trips"."congestion_surcharge" AS "congestion_surcharge", "green_trips"."cbd_congestion_fee" AS "cbd_congestion_fee" FROM "green_trips" WHERE (("green_trips"."passenger_count" = 0) OR ("green_trips"."total_amount" <= 0) OR ("green_trips"."trip_distance" <= 0) OR ("green_trips"."trip_distance" > 100) OR ("green_trips"."dropoff_datetime" < "green_trips"."pickup_datetime") OR (NOT CAST("green_trips"."pickup_datetime" AS DATE) BETWEEN '2025-01-01' AND '2025-01-31'));

CREATE VIEW "v_trip_zone" ("trip_id", "pickup_datetime", "dropoff_datetime", "trip_distance", "total_amount", "pickup_borough", "pickup_zone", "dropoff_borough", "dropoff_zone") AS
SELECT "t"."trip_id" AS "trip_id", "t"."pickup_datetime" AS "pickup_datetime", "t"."dropoff_datetime" AS "dropoff_datetime", "t"."trip_distance" AS "trip_distance", "t"."total_amount" AS "total_amount", "pu"."borough" AS "pickup_borough", "pu"."zone" AS "pickup_zone", "do_"."borough" AS "dropoff_borough", "do_"."zone" AS "dropoff_zone" FROM (("green_trips" AS "t" LEFT JOIN "taxi_zone" AS "pu" ON (("pu"."locationid" = "t"."pulocationid"))) LEFT JOIN "taxi_zone" AS "do_" ON (("do_"."locationid" = "t"."dolocationid")));
